import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"System AI (Mode Bawaan)","description":"","frontmatter":{"title":"System AI (Mode Bawaan)"},"headers":[],"relativePath":"providers/systemai.md","filePath":"providers/systemai.md"}`),a={name:`providers/systemai.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="system-ai-mode-bawaan" tabindex="-1">System AI (Mode Bawaan) <a class="header-anchor" href="#system-ai-mode-bawaan" aria-label="Permalink to “System AI (Mode Bawaan)”">​</a></h1><p><strong>System AI</strong> adalah mode <em>engine</em> bawaan Mikazuki AI — AI-nya Mikazuki sendiri. Kamu tidak perlu punya API key, tidak perlu mengisi <em>Base URL</em>, dan tidak ada apa pun yang harus dikonfigurasi. Buka aplikasi, kirim pesan, Model AI bawaan server langsung merespons.</p><blockquote><p><strong>Analoginya:</strong> Mode System = kamu naik <strong>taksi</strong> (semua diurus, tinggal duduk). Mode BYOK = kamu <strong>menyetir mobil sendiri</strong> (bawa kuncimu sendiri, atur sendiri jalannya). Panduan BYOK ada di <a href="./../byok/">Pengenalan BYOK</a>.</p></blockquote><p>Mode engine bisa diganti kapan saja lewat halaman <strong>/settings/engine</strong> — pilih <strong>System</strong> atau <strong>BYOK</strong>. Selama mode System aktif, kamu sudah memakai AI milik server, tanpa biaya dan tanpa setup.</p><hr><h2 id="dua-jalanku-free-vs-vip" tabindex="-1">Dua Jalanku: Free vs VIP <a class="header-anchor" href="#dua-jalanku-free-vs-vip" aria-label="Permalink to “Dua Jalanku: Free vs VIP”">​</a></h2><p>Di balik layar, Mode System menjalankan dua tingkat layanan yang berbeda. Semua kamu perlu tahu hanyalah perbedaan kapasitasnya:</p><table tabindex="0"><thead><tr><th>Aspek</th><th><strong>Free</strong></th><th><strong>VIP</strong></th></tr></thead><tbody><tr><td>Status akun</td><td>Pengguna biasa</td><td>Pelanggan VIP</td></tr><tr><td><strong>Context window</strong> (memori karakter dalam satu request)</td><td>Standar — nyaman untuk obrolan harian</td><td>Jauh lebih besar — ideal untuk roleplay super panjang</td></tr><tr><td><strong>Panjang jawaban</strong></td><td>Ringkas dan efisien</td><td>Lebih lega</td></tr><tr><td>Ragam respons</td><td>Normal</td><td>Ideal untuk roleplay panjang dan grup besar</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Context window itu memori karakter</p><p>Context window menentukan berapa banyak konteks (riwayat chat, persona, memori) yang bisa dimuat dalam satu request. Tingkat Free tetap nyaman untuk obrolan sehari-hari, tetapi jika kamu suka <em>roleplay</em> super panjang atau <em>group chat</em> besar dengan 255 karakter, konteks VIP membuat karakter jadi nyaris tak pernah &quot;lupa&quot;.</p></div><p><strong>Kapan upgrade ke VIP masuk akal?</strong></p><ul><li>📚 Percakapanmu sering melewati ratusan pesan dan karakter mulai kehilangan jejak → konteks VIP melarutkan masalah ini.</li><li>👥 Kamu main <em>group chat</em> besar sehingga model harus memuat banyak persona sekaligus.</li><li>💆 Kamu ingin kuota/limit yang lebih lega tanpa bergantung kuota gratis server.</li></ul><details class="details custom-block"><summary>Nama model dan API key-nya di mana?</summary><p>Itulah keindahan Mode System: semua model, endpoint, dan kunci API <strong>adalah rahasia server</strong>. Kamu tidak pernah mengelolanya — tidak ada dropdown model, tidak ada key yang harus diisi. Server Mikazuki yang memilih dan mengatur penyedia di belakang layar, sehingga nanti jika model di-upgrade, kamu otomatis ikut menikmatinya.</p></details><hr><h2 id="yang-masih-bisa-kamu-setel-di-mode-system" tabindex="-1">Yang Masih Bisa Kamu Setel di Mode System <a class="header-anchor" href="#yang-masih-bisa-kamu-setel-di-mode-system" aria-label="Permalink to “Yang Masih Bisa Kamu Setel di Mode System”">​</a></h2><p>Walaupun parameter generasi terkunci server, pengalaman berkarakter milikmu tetap penuh kustomisasi:</p><h3 id="prompt-engine-mikazuki-vs-halostory" tabindex="-1">Prompt Engine: mikazuki vs halostory <a class="header-anchor" href="#prompt-engine-mikazuki-vs-halostory" aria-label="Permalink to “Prompt Engine: mikazuki vs halostory”">​</a></h3><p>Di bagian <strong>Prompt Engine</strong> di halaman settings yang sama, kamu bisa memilih dua ragam mesin prompt:</p><table tabindex="0"><thead><tr><th>Opsi</th><th>Penjelasan</th></tr></thead><tbody><tr><td><strong>mikazuki</strong> <em>(default)</em></td><td>Gaya prompt terbaru, dikalibrasi khusus untuk Mikazuki AI — paling optimal untuk bahasa santai Indonesia dan format respons terkini.</td></tr><tr><td><strong>halostory</strong></td><td>Mode kesetaraan <em>legacy</em> dengan era HaloStory lama. berguna jika kamu merasa respons karakter terasa &quot;berbeda&quot; dari versi lama dan ingin nuansa klasik itu kembali.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Catatan mode halostory</p><p>Mode <code>halostory</code> dipertahankan murni untuk <em>parity</em> aplikasi lama. Untuk karakter baru atau pengguna baru, tetap disarankan memakai <code>mikazuki</code> karena itulah mode yang terus dikembangkan.</p></div><h3 id="fitur-memori-karakter-—-sama-persis-dengan-byok" tabindex="-1">Fitur memori &amp; karakter — sama persis dengan BYOK <a class="header-anchor" href="#fitur-memori-karakter-—-sama-persis-dengan-byok" aria-label="Permalink to “Fitur memori &amp; karakter — sama persis dengan BYOK”">​</a></h3><p>Mode System hanya mengganti &quot;otak&quot; yang memproses jawaban; seluruh fitur Mikazuki tidak berubah:</p><ul><li>✅ <strong>Memori Chat &amp; Global Memories (VIP)</strong> — tetap jalan. Per request, sistem mengirim maksimal <strong>9 memori terbaru</strong> untuk menjaga respons tetap fokus dan hemat konteks.</li><li>✅ <strong>Summary / Auto-Summarize</strong> — ringkasan batch percakapan tetap disuntikkan (satu batch ringkasan terakhir per request).</li><li>✅ <strong>Persona, System Notes, gaya bahasa karakter</strong> — identik.</li><li>✅ <strong>Bond System</strong> — XP dan level ikatan tetap bertambah.</li><li>✅ <strong>Dynamic Delete (Hapus Lanjutan)</strong> — kurasi memori tetap tersedia.</li></ul><hr><h2 id="kontrak-kebijakan-mode-system" tabindex="-1">Kontrak &amp; Kebijakan Mode System <a class="header-anchor" href="#kontrak-kebijakan-mode-system" aria-label="Permalink to “Kontrak &amp; Kebijakan Mode System”">​</a></h2><p><strong>Kenapa <code>temperature</code>, <code>max_tokens</code>, dan context window tidak bisa diutak-atik?</strong></p><p>Parameter generasi di Mode System disetel penuh oleh server — kamu tidak bisa mengubah <code>temperature</code>, <code>top_p</code>, batas token keluaran, maupun context window. Ini keputusan sadar, bukan pembatasan kikuk:</p><ol><li><strong>Konsistensi</strong> — Server telah mengkalibrasi semua nilai ini agar model menghasilkan respons roleplay yang stabil dan tidak &quot;melar&quot; dari persona karakter.</li><li><strong>Anti-abuse &amp; pemerataan</strong> — Kuota gratis harus bisa dirasakan semua pengguna. Pembatasan token mencegah segelintir pengguna menghabiskan kapasitas gratis dengan request raksasa.</li><li><strong>Stabilitas layanan</strong> — Server menerapkan <em>rate limit</em> dan <em>throttling</em> internal agar streaming tetap sehat bagi semua, bukan hanya yang paling cepat klik.</li></ol><div class="tip custom-block"><p class="custom-block-title">Butuh kendali penuh?</p><p>Jika kamu ingin parameter canggih — memilih model sendiri, <code>temperature</code> bebas, context window kustom — itu tugas <strong>BYOK</strong>. Bawa kuncimu ke <a href="./../byok/">Pengenalan BYOK</a> dan mulai dari halaman <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>.</p></div><hr><h2 id="faq-singkat" tabindex="-1">FAQ Singkat <a class="header-anchor" href="#faq-singkat" aria-label="Permalink to “FAQ Singkat”">​</a></h2><details class="details custom-block"><summary>Apakah Mode System gratis?</summary><p>Ya. Tingkat <strong>Free</strong> tersedia untuk semua akun tanpa biaya, dengan kuota dan batas panjang jawaban yang berlaku. Upgrade <strong>VIP</strong> memperluas memori karakter (context window) dan panjang balasan secara signifikan, plus fitur Global Memory lebih luas.</p></details><details class="details custom-block"><summary>Data obrolanku di Mode System tersimpan di server?</summary><p>Tidak. Sama seperti BYOK, riwayat obrolanmu disimpan <strong>lokal di perangkatmu</strong> (IndexedDB). Server hanya memproses request saat percakapan berlangsung dan tidak menyimpan isi chat-mu di database.</p></details><details class="details custom-block"><summary>Kenapa jawaban kadang terasa terpotong?</summary><p>Mode System membatasi panjang keluaran per balasan demi pemerataan kuota. Kalau kamu butuh balasan yang lebih panjang dan mendetail, pindahkan obrolan ke <strong>BYOK</strong> di mana <code>max_tokens</code> kamu tentukan sendiri — atau pecah interaksi jadi pesan-pesan lebih pendek.</p></details><hr><h2 id="selanjutnya" tabindex="-1">Selanjutnya <a class="header-anchor" href="#selanjutnya" aria-label="Permalink to “Selanjutnya”">​</a></h2><ul><li>Ingin model dan parameter sesukamu? Masuk ke dunia <a href="./../byok/">BYOK (Bring Your Own Key)</a>.</li><li>Kenali arsitektur memori karakter di <a href="./../pengenalan.html">Pengenalan</a>.</li><li>Atur ulang memori karaktermu lewat fitur <strong>Hapus Lanjutan (Dynamic Delete)</strong> di dalam aplikasi.</li></ul>`,36)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};